  old_start: (ev.start && (ev.start.dateTime || ev.start.date)) || '',
  new_start: REQ.new_start_iso, new_end: REQ.new_end_iso,
  notify, bookerRef, bookerName, engInitials, engFilter, roomNote } }];

// Google gives an all-day event as a bare date ("2026-10-06", end exclusive). new Date() reads that as UTC
// midnight - 08:00 in Manila - so a 6-7 AM booking slipped past an all-day hold (review 29 Sep). A bare date
// is Manila midnight; a dateTime keeps its own offset.
const evMs = v => { const s = String(v || ''); return /^\d{4}-\d{2}-\d{2}$/.test(s) ? Date.parse(s + 'T00:00:00+08:00') : new Date(s).getTime(); };
// The new window has to be free for the same rooms - excluding the booking
// being moved, which would otherwise collide with itself.
const R = $('Resolve Booking').first().json;
const raw = $input.first().json || {};
// PENDING 51 (2026-09-28): a failed read of the new window used to count as "no events" - the move then went
// ahead into a room nobody had checked. A read that did not return a calendar is a refusal.
if (!Array.isArray(raw.items) || raw.nextPageToken) {
  return [{ json: { verdict:'REJECTED', reason:'LOOKUP_FAILED',
    human:'Nothing was moved - the calendar could not be read for the new time, so it could not be checked for clashes. The original booking is unchanged. Tell the requester and offer to try again.' } }];
}
const items = raw.items.filter(e => e.status !== 'cancelled');
const mine = R.attendees.map(a => String(a.email).toLowerCase());
const loc = String(R.location || '').toLowerCase();
const ns = new Date(R.new_start).getTime(), ne = new Date(R.new_end).getTime();

const clashes = [];
for (const e of items) {
  if (String(e.id) === String(R.original_id)) continue;
  const s = evMs(e.start && (e.start.dateTime || e.start.date));
  const t = evMs(e.end && (e.end.dateTime || e.end.date));
  if (!(s < ne && t > ns)) continue;
  const emails = (e.attendees || []).map(a => String(a.email || '').toLowerCase());
  const sameRoom = mine.some(m => emails.indexOf(m) !== -1)
    || (loc && String(e.location || '').toLowerCase() === loc);
