       + 'say the old one has to be deleted by hand.' } }];

const v = $input.first().json || {};
return [{ json: { status:'REJECTED', reason: v.reason || 'FAILED',
  human: v.human || 'Nothing was moved and the reason is unclear. Tell the requester it did not go through.' } }];

// Notification recipients for an authorized change: the booker (owner) always, plus the
