const bookerName = co.bookerName || 'the booker';
push(bookerId, bookerName, 'Heads up - your booking "' + title + '" on ' + dateStr + ' was ' + VERB + roomNote + ' by ' + actor + '.', true);
let eng = {};
try { eng = $('Lookup Engineer').first().json || {}; } catch (e) {}
const ef = eng.fields || {};
const engId = ef['Slack User ID'] || '';
const engName = ef['Name'] || '';
if (engId && engId !== bookerId && engId !== actorId) {
  push(engId, engName, 'Heads up - the session "' + title + '" you are assigned to on ' + dateStr + ' was ' + VERB + roomNote + ' by ' + actor + '.', true);
}
